-- Plan B Task 1: the Supplify HoReCa category tree (departments -> leaf categories).
-- The 16 original platform rows keep their id, name and slug (re-parented by 0240); this file
-- adds Arabic / French names, multilingual aliases (English, Arabic, Lebanese, French) and
-- icon keys (Phosphor icon names, kebab-case), and inserts the narrower leaves beside them.
-- Aliases are stored lower-case in natural form; lib/category-matcher.js normalises them.
-- Idempotent: an upsert on the platform slug; names of existing rows are never changed.

INSERT INTO product_category
  (slug, parent_category_id, name, name_ar, name_fr, icon_key, display_order, aliases)
