LEFT JOIN product_category parent
  ON parent.slug = v.parent_slug AND parent.supplier_id IS NULL
ON CONFLICT (slug) WHERE supplier_id IS NULL DO UPDATE SET
  name_ar = EXCLUDED.name_ar,
  name_fr = EXCLUDED.name_fr,
  icon_key = EXCLUDED.icon_key,
  aliases = EXCLUDED.aliases,
  parent_category_id = COALESCE(product_category.parent_category_id, EXCLUDED.parent_category_id),
  updated_at = now();
